#!/usr/bin/env python3
"""Create audiobook from Paul Graham essays."""

import os
import re
import subprocess
import requests
from bs4 import BeautifulSoup
from gtts import gTTS
import sys

def fetch_article_content(url):
    """Fetch article content using requests and BeautifulSoup."""
    try:
        response = requests.get(url)
        response.raise_for_status()

        soup = BeautifulSoup(response.content, 'html.parser')

        # specific extraction for paulgraham.com to avoid too much noise
        # His essays are usually in a table structure. The main content is often inside <font> tags or just the body.
        # Let's try to find the main font tag which usually contains the text.
        # But looking at his source, it's often:
        # <body><table><tr><td><img...></td><td> ... content ... </td></tr></table></body>
        # A simple get_text() is usually fine as long as we clean it up.

        text = soup.get_text(separator=' ', strip=True)
        return text
    except Exception as e:
        print(f"Error fetching {url}: {e}")
        return ""

def clean_text_for_tts(text):
    """Clean text for better TTS output."""
    # Remove excessive whitespace
    text = re.sub(r'\s+', ' ', text)

    # Remove some common navigation text if present (heuristic)
    # Paul Graham's site usually has a footer.

    # Remove URLs
    text = re.sub(r'http[s]?://\S+', ' ', text)

    return text.strip()

def chunk_text(text, max_chars=4000):
    """Split text into chunks at sentence boundaries."""
    # Split by sentence endings, keeping the punctuation
    sentences = re.split(r'(?<=[.!?])\s+', text)
    chunks = []
    current_chunk = ""

    for sentence in sentences:
        if len(current_chunk) + len(sentence) < max_chars:
            current_chunk += sentence + " "
        else:
            if current_chunk:
                chunks.append(current_chunk.strip())
            current_chunk = sentence + " "

    if current_chunk:
        chunks.append(current_chunk.strip())

    return chunks

def create_with_elevenlabs(text, output_path):
    """Generate audiobook using ElevenLabs API."""
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    # Using a default voice if specific one not known/available, or let API pick.
    # The skill doc suggested "21m00Tcm4TlvDq8ikWAM" (Rachel).
    voice_id = "21m00Tcm4TlvDq8ikWAM" 

    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    print(f"Converting {len(text)} chars with ElevenLabs...")

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        print(f"Processing chunk {i+1}/{len(chunks)}...")

        try:
            response = requests.post(
                f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
                headers={
                    "xi-api-key": api_key,
                    "Content-Type": "application/json"
                },
                json={
                    "text": chunk,
                    "model_id": "eleven_turbo_v2_5",
                    "voice_settings": {"stability": 0.5, "similarity_boost": 0.75}
                }
            )

            if response.status_code == 200:
                with open(chunk_file, "wb") as f:
                    f.write(response.content)
                audio_files.append(chunk_file)
            else:
                print(f"Error: {response.status_code} - {response.text}")
                # Don't fail completely, try to continue or fallback? 
                # For now, return False to trigger fallback if designed, or just fail.
                return False
        except Exception as e:
            print(f"Exception calling ElevenLabs: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def create_with_openai(text, output_path):
    """Generate audiobook using OpenAI TTS API."""
    api_key = os.environ.get("OPENAI_API_KEY")
    chunks = chunk_text(text, max_chars=4000)
    audio_files = []

    print(f"Converting {len(text)} chars with OpenAI...")

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        print(f"Processing chunk {i+1}/{len(chunks)}...")

        try:
            response = requests.post(
                "https://api.openai.com/v1/audio/speech",
                headers={
                    "Authorization": f"Bearer {api_key}",
                    "Content-Type": "application/json"
                },
                json={
                    "model": "tts-1",
                    "input": chunk,
                    "voice": "onyx",
                    "response_format": "mp3"
                }
            )

            if response.status_code == 200:
                with open(chunk_file, "wb") as f:
                    f.write(response.content)
                audio_files.append(chunk_file)
            else:
                print(f"Error: {response.status_code} - {response.text}")
                return False
        except Exception as e:
            print(f"Exception calling OpenAI: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def create_with_gtts(text, output_path):
    """Generate audiobook using gTTS (free)."""
    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    print(f"Converting {len(text)} chars with gTTS...")

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        print(f"Processing chunk {i+1}/{len(chunks)}...")

        try:
            tts = gTTS(text=chunk, lang='en', slow=False)
            tts.save(chunk_file)
            audio_files.append(chunk_file)
        except Exception as e:
            print(f"Exception calling gTTS: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def concatenate_audio(audio_files, output_path):
    """Concatenate multiple audio files using ffmpeg."""
    if not audio_files:
        return False

    list_file = "/tmp/audio_list.txt"
    with open(list_file, "w") as f:
        for audio_file in audio_files:
            f.write(f"file '{audio_file}'\n")

    print(f"Concatenating {len(audio_files)} files to {output_path}...")
    try:
        result = subprocess.run([
            "ffmpeg", "-y", "-f", "concat", "-safe", "0",
            "-i", list_file, "-c", "copy", output_path
        ], capture_output=True)

        if result.returncode != 0:
            print(f"ffmpeg error: {result.stderr.decode()}")
            return False

        # Cleanup
        for f in audio_files:
            if os.path.exists(f):
                os.unlink(f)
        if os.path.exists(list_file):
            os.unlink(list_file)

        return True
    except Exception as e:
        print(f"Exception during concatenation: {e}")
        return False

def create_audiobook(text, output_path):
    """Convert text to audiobook with automatic TTS provider selection."""

    # Priority: ElevenLabs > OpenAI > gTTS
    if os.environ.get("ELEVENLABS_API_KEY"):
        print("Using ElevenLabs TTS")
        if create_with_elevenlabs(text, output_path):
            return True
        print("ElevenLabs failed, trying next provider...")

    if os.environ.get("OPENAI_API_KEY"):
        print("Using OpenAI TTS")
        if create_with_openai(text, output_path):
            return True
        print("OpenAI failed, trying next provider...")

    print("Using gTTS")
    return create_with_gtts(text, output_path)

def main():
    urls = [
        "http://paulgraham.com/ds.html",
        "https://paulgraham.com/foundermode.html"
    ]

    full_text = ""

    for url in urls:
        print(f"Fetching {url}...")
        content = fetch_article_content(url)
        if content:
            cleaned = clean_text_for_tts(content)
            full_text += f"\n\n--- Next Essay ---\n\n{cleaned}"
        else:
            print(f"Failed to fetch content for {url}")

    if not full_text.strip():
        print("No text found to convert.")
        sys.exit(1)

    output_path = "/root/audiobook.mp3"
    if create_audiobook(full_text, output_path):
        print(f"Audiobook created at {output_path}")
    else:
        print("Failed to create audiobook.")
        sys.exit(1)

if __name__ == "__main__":
    main()

